#!/usr/bin/env Rscript

suppressPackageStartupMessages(library(Rcpp))
options(stringsAsFactors=FALSE,warn=1)
args<-commandArgs(trailingOnly=TRUE)
arg_value<-function(name,default){z<-grep(paste0("^--",name,"="),args,value=TRUE);if(length(z))sub(paste0("^--",name,"="),"",z[[1]])else default}
mode<-arg_value("mode","quick");if(!mode%in%c("quick","full"))stop("--mode must be quick or full")
n<-as.integer(arg_value("n","100"));p<-as.integer(arg_value("p","10"));datasets<-as.integer(arg_value("datasets",if(mode=="quick")"1" else "20"));chains<-as.integer(arg_value("chains",if(mode=="quick")"2" else "4"));budget<-as.numeric(arg_value("budget",if(mode=="quick")"0.25" else "1"));burn<-as.integer(arg_value("burn",if(mode=="quick")"100" else "500"));lambdas<-as.numeric(strsplit(arg_value("lambdas","0.2,0.5,0.8,1.1,1.5"),",",fixed=TRUE)[[1]])
out_dir<-arg_value("output","Simulations/Exact_Score_Sensitivity/Results/New_Run");marginal_audit<-arg_value("marginal-audit",file.path("Simulations/Validation/Results/New_Run/Marginal_Scores/summary.csv"));production_audit<-arg_value("production-audit",file.path("Simulations/Validation/Results/New_Run/Gaussian_Updates/summary.csv"))
for(f in c(marginal_audit,production_audit))if(!file.exists(f)||!isTRUE(read.csv(f)$passed[[1]]))stop("Required proposal audit has not passed: ",f)
if(p>20L)stop("Exact enumeration is restricted to p <= 20");source(file.path("Simulations/Validation/gaussian_support.R"));revision_initialize(out_dir,require_audit=TRUE);for(audit_path in c(marginal_audit,production_audit))revision_require_audit(dirname(audit_path))
Rcpp::sourceCpp(file.path("Simulations/gaussian_kernels.cpp"),cacheDir=file.path("Simulations/.rcpp_cache"),rebuild=FALSE)
ess_basic<-function(x){if(length(x)<20||!is.finite(var(x))||var(x)==0)return(NA_real_);z<-as.numeric(acf(x,lag.max=min(length(x)-1,1000),plot=FALSE)$acf)[-1];m<-length(z)-length(z)%%2;if(m<2)return(length(x));q<-z[seq(1,m,2)]+z[seq(2,m,2)];k<-match(TRUE,q<=0,nomatch=length(q)+1);keep<-if(k==1)numeric()else q[seq_len(k-1)];min(length(x),length(x)/(1+2*sum(keep)))}
simulate_data<-function(seed){set.seed(seed);S<-outer(seq_len(p),seq_len(p),function(i,j).65^abs(i-j));X<-matrix(rnorm(n*p),n,p)%*%chol(S);X<-unclass(scale(X));active<-unique(pmin(p,c(2L,5L,8L)));beta<-numeric(p);beta[active]<-rep(c(1,-1,1),length.out=length(active));list(X=X,y=as.numeric(.4+X%*%beta+rnorm(n)),active=active)}
make_starts<-function(active){z<-replicate(chains,integer(p),simplify=FALSE);if(chains>=2)z[[2]][active]<-1L;if(chains>=3)z[[3]][]<-rep(0:1,length.out=p);if(chains>=4){set.seed(991);z[[4]][sample.int(p,min(length(active),p))]<-1L};z}
specs<-rbind(data.frame(score=c("f","bic","marginal"),regime="online",lambda=.7),do.call(rbind,lapply(c("f","bic","marginal"),function(s)data.frame(score=s,regime="fixed",lambda=lambdas))))
rows<-list();pips<-list();adapt<-list();alignment<-list();id<-0L;aid<-0L;alid<-0L
for(dataset in seq_len(datasets)){dat<-simulate_data(20273000L+dataset);states<-as.matrix(expand.grid(rep(list(0:1),p)));logp<-apply(states,1,function(g)evaluate_exact_gaussian_log_target(dat$y,dat$X,as.integer(g)));exact<-exp(logp-max(logp));exact<-exact/sum(exact);exact_pip<-colSums(states*exact);starts<-make_starts(dat$active)
  for(score in c("f","bic","marginal")){cors<-numeric(nrow(states));for(si in seq_len(nrow(states))){g<-as.integer(states[si,]);proposal<-evaluate_fast_similarity_probabilities(dat$y,dat$X,g,score,1,FALSE,0);neighbor<-bitwXor(si-1L,bitwShiftL(1L,0:(p-1L)))+1L;cors[si]<-suppressWarnings(cor(log(proposal),logp[neighbor]-logp[si],method="spearman"))};alid<-alid+1L;alignment[[alid]]<-data.frame(dataset=dataset,score=score,posterior_weighted_rank_correlation=sum(exact*replace(cors,!is.finite(cors),0)),unweighted_rank_correlation=mean(cors,na.rm=TRUE))}
  for(si in seq_len(nrow(specs)))for(chain in seq_len(chains)){sp<-specs[si,];set.seed(20274000L+dataset*10000L+si*100L+chain);fit<-run_optimized_similarity_scaling(dat$y,dat$X,sp$score,starts[[chain]],budget,burn,max_iterations=1000000L,lambda_initial=sp$lambda,adapt_lambda=sp$regime=="online",balance_directions=TRUE,adaptation_metric="diversity",target_effective_neighbors=max(5,.025*p),adaptation_gain=.5,adaptation_decay=.6,adaptation_offset=100,uniform_mixture=.02);emp<-tabulate(as.integer(fit$model_index)+1L,nbins=2^p)/length(fit$model_index);es<-ess_basic(fit$model_size);et<-ess_basic(fit$log_target);id<-id+1L;rows[[id]]<-data.frame(dataset=dataset,chain=chain,score=sp$score,regime=sp$regime,lambda_initial=sp$lambda,lambda_final=fit$final_lambda,seconds=fit$total_seconds,iterations=fit$iterations,acceptance=fit$postburn_acceptance_rate,mean_effective_neighbors=fit$mean_proposal_effective_neighbors,mean_entropy=fit$mean_proposal_entropy,mean_max_probability=fit$mean_max_proposal_probability,ess_model_size_per_second=es/fit$total_seconds,ess_log_target_per_second=et/fit$total_seconds,mean_pip_error=mean(abs(fit$pips-exact_pip)),max_pip_error=max(abs(fit$pips-exact_pip)),total_variation=.5*sum(abs(emp-exact)));pips[[id]]<-data.frame(dataset=dataset,chain=chain,score=sp$score,regime=sp$regime,lambda_initial=sp$lambda,variable=seq_len(p),active=seq_len(p)%in%dat$active,estimate=fit$pips,exact=exact_pip);keep<-unique(round(seq(1,length(fit$lambda_trace),length.out=min(250,length(fit$lambda_trace)))));aid<-aid+1L;adapt[[aid]]<-data.frame(dataset=dataset,chain=chain,score=sp$score,regime=sp$regime,lambda_initial=sp$lambda,retained_iteration=keep,lambda=fit$lambda_trace[keep]);message(sprintf("dataset=%d/%d score=%s regime=%s lambda=%.2f chain=%d/%d",dataset,datasets,sp$score,sp$regime,sp$lambda,chain,chains))}}
raw<-do.call(rbind,rows);pip<-do.call(rbind,pips);trajectories<-do.call(rbind,adapt);alignment<-do.call(rbind,alignment);num<-setdiff(names(raw)[vapply(raw,is.numeric,logical(1))],c("dataset","chain","lambda_initial"));summary<-aggregate(raw[num],raw[c("score","regime","lambda_initial")],mean,na.rm=TRUE)
write.csv(raw,file.path(out_dir,"chain_metrics.csv"),row.names=FALSE);write.csv(summary,file.path(out_dir,"method_summary.csv"),row.names=FALSE);write.csv(pip,file.path(out_dir,"pip_comparison.csv"),row.names=FALSE);write.csv(alignment,file.path(out_dir,"score_alignment.csv"),row.names=FALSE);write.csv(trajectories,file.path(out_dir,"adaptive_trajectories_thinned.csv"),row.names=FALSE);writeLines(c(paste("mode:",mode),paste("n:",n),paste("p:",p),paste("datasets:",datasets),paste("chains:",chains),paste("budget_seconds:",budget),paste("burn:",burn),paste("fixed_lambda_grid:",paste(lambdas,collapse=",")),"engine: optimized rank-one similarity proposals","online adaptation: balanced directions, 2% mixture, diminishing diversity adaptation throughout sampling","marginal score: sum of univariate evidence in candidate model divided by sqrt(model size)"),file.path(out_dir,"manifest.txt"));writeLines(capture.output(sessionInfo()),file.path(out_dir,"sessionInfo.txt"));saveRDS(list(raw=raw,summary=summary,pip=pip,alignment=alignment,trajectories=trajectories),file.path(out_dir,"chain_results.rds"),compress="xz");print(summary,row.names=FALSE)
